/* ==========================================================================
   VETRI APEX ACADEMY - MAIN STYLESHEET
   A modern, professional, fully responsive design for Chennai's premier coaching institute.
   ========================================================================== */

/* --- CSS Variables & Design System --- */
:root {
  --primary: #0A1E3F;
  --primary-rgb: 10, 30, 63;
  --primary-light: #16325C;
  --primary-dark: #061226;
  --accent-gold: #F59E0B;
  --accent-gold-hover: #D97706;
  --accent-gold-light: #FEF3C7;
  --brand-blue: #2563EB;
  --brand-cyan: #06B6D4;
  --brand-teal: #0D9488;
  --brand-purple: #7C3AED;
  --brand-emerald: #059669;
  --whatsapp: #25D366;
  --whatsapp-dark: #128C7E;
  --whatsapp-light: #DCFCE7;

  --bg-body: #F8FAFC;
  --bg-surface: #FFFFFF;
  --bg-subtle: #F1F5F9;
  --bg-dark: #0B192C;

  --text-main: #0F172A;
  --text-muted: #475569;
  --text-light: #94A3B8;
  --text-white: #FFFFFF;

  --border-light: #E2E8F0;
  --border-focus: #3B82F6;
  --danger: #EF4444;
  --success: #10B981;

  --font-heading: 'Outfit', sans-serif;
  --font-body: 'Plus Jakarta Sans', sans-serif;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(10, 30, 63, 0.08), 0 2px 4px -2px rgba(10, 30, 63, 0.06);
  --shadow-lg: 0 10px 25px -3px rgba(10, 30, 63, 0.1), 0 4px 6px -4px rgba(10, 30, 63, 0.05);
  --shadow-xl: 0 20px 35px -5px rgba(10, 30, 63, 0.15), 0 8px 10px -6px rgba(10, 30, 63, 0.08);
  --shadow-glow: 0 0 25px rgba(245, 158, 11, 0.35);

  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --radius-full: 9999px;

  --transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  --transition-slow: all 0.4s ease;
}

/* --- Base & Reset --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  color: var(--text-main);
  background-color: var(--bg-body);
  line-height: 1.6;
  overflow-x: hidden;
  position: relative;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
  transition: var(--transition);
}

ul {
  list-style: none;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

button, input, select, textarea {
  font-family: inherit;
  font-size: inherit;
  outline: none;
}

.container {
  width: 100%;
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 20px;
}

.text-center {
  text-align: center;
}

/* --- Typography Helpers --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  color: var(--primary);
  font-weight: 700;
  line-height: 1.25;
}

.section {
  padding: 85px 0;
  position: relative;
}

.section-header {
  max-width: 760px;
  margin: 0 auto 50px auto;
}

.section-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 16px;
  background-color: rgba(37, 99, 235, 0.1);
  color: var(--brand-blue);
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border-radius: var(--radius-full);
  margin-bottom: 14px;
}

.section-tag.light {
  background-color: rgba(255, 255, 255, 0.15);
  color: var(--accent-gold);
}

.section-title {
  font-size: 2.35rem;
  margin-bottom: 16px;
  letter-spacing: -0.02em;
}

.section-subtitle {
  font-size: 1.1rem;
  color: var(--text-muted);
  line-height: 1.65;
}

.highlight-gradient {
  background: linear-gradient(135deg, #2563EB, #F59E0B);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 12px 24px;
  font-weight: 600;
  font-size: 0.95rem;
  border-radius: var(--radius-md);
  border: 1.5px solid transparent;
  cursor: pointer;
  transition: var(--transition);
  text-align: center;
  white-space: nowrap;
}

.btn-primary {
  background-color: var(--primary);
  color: var(--text-white);
  box-shadow: 0 4px 12px rgba(10, 30, 63, 0.25);
}

.btn-primary:hover {
  background-color: var(--primary-light);
  transform: translateY(-2px);
  box-shadow: 0 6px 18px rgba(10, 30, 63, 0.35);
}

.btn-secondary {
  background-color: var(--accent-gold);
  color: var(--primary-dark);
  font-weight: 700;
  box-shadow: 0 4px 14px rgba(245, 158, 11, 0.3);
}

.btn-secondary:hover {
  background-color: var(--accent-gold-hover);
  color: #fff;
  transform: translateY(-2px);
}

.btn-outline {
  background: transparent;
  color: var(--primary);
  border-color: var(--primary);
}

.btn-outline:hover {
  background-color: var(--primary);
  color: #fff;
}

.btn-whatsapp {
  background-color: var(--whatsapp);
  color: #fff;
  font-weight: 600;
}

.btn-whatsapp:hover {
  background-color: var(--whatsapp-dark);
  color: #fff;
  transform: translateY(-2px);
  box-shadow: 0 4px 14px rgba(37, 211, 102, 0.4);
}

.btn-sm {
  padding: 8px 16px;
  font-size: 0.85rem;
  border-radius: var(--radius-sm);
}

.btn-lg {
  padding: 15px 30px;
  font-size: 1.05rem;
  border-radius: var(--radius-md);
}

.full-width {
  width: 100%;
}

.mb-2 {
  margin-bottom: 8px;
}

.mt-1 {
  margin-top: 4px;
}

.mt-3 {
  margin-top: 14px;
}

/* --- Top Announcement Bar --- */
.top-bar {
  background-color: var(--primary-dark);
  color: #E2E8F0;
  font-size: 0.82rem;
  padding: 8px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.top-bar-content {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
}

.top-bar-left, .top-bar-right {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.badge-pill {
  background: var(--accent-gold);
  color: var(--primary-dark);
  padding: 2px 10px;
  border-radius: var(--radius-full);
  font-weight: 700;
  font-size: 0.72rem;
  text-transform: uppercase;
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.pulse {
  animation: pulseGlow 2s infinite;
}

@keyframes pulseGlow {
  0% { transform: scale(1); box-shadow: 0 0 0 0 rgba(245, 158, 11, 0.7); }
  70% { transform: scale(1.03); box-shadow: 0 0 0 8px rgba(245, 158, 11, 0); }
  100% { transform: scale(1); box-shadow: 0 0 0 0 rgba(245, 158, 11, 0); }
}

.top-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: #CBD5E1;
}

.top-link:hover {
  color: var(--accent-gold);
}

.campuses-tag {
  color: #94A3B8;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

/* --- Header / Navigation Bar --- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background-color: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-light);
  box-shadow: 0 2px 15px rgba(0, 0, 0, 0.04);
  transition: var(--transition);
}

.site-header.scrolled {
  padding: 4px 0;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
}

.header-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 74px;
}

/* Logo */
.brand-logo {
  display: flex;
  align-items: center;
  gap: 12px;
}

.logo-icon {
  width: 44px;
  height: 44px;
  background: linear-gradient(135deg, var(--primary), #1E40AF);
  color: var(--accent-gold);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  box-shadow: 0 4px 10px rgba(10, 30, 63, 0.2);
}

.logo-icon.small {
  width: 36px;
  height: 36px;
  font-size: 1.1rem;
}

.logo-text {
  display: flex;
  flex-direction: column;
}

.brand-name {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  color: var(--primary);
  line-height: 1.1;
}

.brand-tagline {
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: var(--accent-gold-hover);
}

/* Nav Menu */
.nav-menu {
  display: flex;
  align-items: center;
}

.nav-list {
  display: flex;
  align-items: center;
  gap: 26px;
}

.nav-link {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-muted);
  position: relative;
  padding: 6px 0;
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2.5px;
  background: var(--accent-gold);
  border-radius: 2px;
  transition: var(--transition);
}

.nav-link:hover, .nav-link.active {
  color: var(--primary);
}

.nav-link:hover::after, .nav-link.active::after {
  width: 100%;
}

/* Header Actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.btn-whatsapp-header {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  background-color: var(--whatsapp-light);
  color: var(--whatsapp-dark);
  padding: 8px 14px;
  border-radius: var(--radius-full);
  font-size: 0.85rem;
  font-weight: 700;
  border: 1px solid rgba(37, 211, 102, 0.3);
  transition: var(--transition);
}

.btn-whatsapp-header i {
  font-size: 1.1rem;
  color: var(--whatsapp);
}

.btn-whatsapp-header:hover {
  background-color: var(--whatsapp);
  color: #fff;
}

.btn-whatsapp-header:hover i {
  color: #fff;
}

.mobile-toggle {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 6px;
  flex-direction: column;
  gap: 5px;
}

.mobile-toggle .bar {
  width: 24px;
  height: 2.5px;
  background-color: var(--primary);
  border-radius: 2px;
  transition: var(--transition);
}

/* --- Mobile Drawer Menu --- */
.mobile-drawer-overlay {
  position: fixed;
  inset: 0;
  background: rgba(10, 30, 63, 0.65);
  backdrop-filter: blur(4px);
  z-index: 1999;
  opacity: 0;
  visibility: hidden;
  transition: var(--transition);
}

.mobile-drawer-overlay.active {
  opacity: 1;
  visibility: visible;
}

.mobile-drawer {
  position: fixed;
  top: 0;
  right: -320px;
  width: 300px;
  height: 100%;
  background: #ffffff;
  z-index: 2000;
  box-shadow: -5px 0 25px rgba(0, 0, 0, 0.15);
  transition: right 0.35s cubic-bezier(0.16, 1, 0.3, 1);
  display: flex;
  flex-direction: column;
}

.mobile-drawer.open {
  right: 0;
}

.drawer-header {
  padding: 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--border-light);
}

.drawer-close {
  background: var(--bg-subtle);
  border: none;
  width: 36px;
  height: 36px;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 1.2rem;
  transition: var(--transition);
}

.drawer-close:hover {
  background: var(--danger);
  color: #fff;
}

.drawer-body {
  padding: 24px 20px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  height: 100%;
  overflow-y: auto;
}

.drawer-nav {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.drawer-link {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 12px 14px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-main);
  border-radius: var(--radius-md);
  transition: var(--transition);
}

.drawer-link i {
  width: 20px;
  color: var(--brand-blue);
  font-size: 1.1rem;
}

.drawer-link:hover {
  background: var(--bg-subtle);
  color: var(--primary);
  transform: translateX(4px);
}

.drawer-footer {
  padding-top: 20px;
  border-top: 1px solid var(--border-light);
}

/* --- Hero Section --- */
.hero-section {
  position: relative;
  background: linear-gradient(145deg, #0A1E3F 0%, #102A54 50%, #06152B 100%);
  color: #fff;
  padding: 70px 0 90px 0;
  overflow: hidden;
}

.hero-bg-shapes {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.shape {
  position: absolute;
  border-radius: 50%;
  filter: blur(80px);
  opacity: 0.25;
}

.shape-1 {
  width: 450px;
  height: 450px;
  background: #3B82F6;
  top: -100px;
  right: -50px;
}

.shape-2 {
  width: 400px;
  height: 400px;
  background: #F59E0B;
  bottom: -80px;
  left: -80px;
  opacity: 0.18;
}

.shape-grid {
  position: absolute;
  inset: 0;
  background-image: radial-gradient(rgba(255, 255, 255, 0.08) 1px, transparent 1px);
  background-size: 28px 28px;
  opacity: 0.6;
}

.hero-container {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  align-items: center;
  gap: 45px;
  position: relative;
  z-index: 2;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.18);
  padding: 6px 16px;
  border-radius: var(--radius-full);
  margin-bottom: 22px;
  backdrop-filter: blur(8px);
}

.rating-stars {
  background: var(--accent-gold);
  color: var(--primary-dark);
  font-weight: 800;
  font-size: 0.78rem;
  padding: 2px 8px;
  border-radius: var(--radius-full);
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.badge-text {
  font-size: 0.84rem;
  font-weight: 500;
  color: #E2E8F0;
}

.hero-title {
  font-size: 3.1rem;
  font-weight: 800;
  color: #FFFFFF;
  line-height: 1.15;
  margin-bottom: 20px;
  letter-spacing: -0.02em;
}

.hero-subtitle {
  font-size: 1.15rem;
  color: #CBD5E1;
  line-height: 1.65;
  margin-bottom: 34px;
  max-width: 600px;
}

.hero-cta-group {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 45px;
}

.btn-whatsapp-hero {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  background: rgba(37, 211, 102, 0.15);
  border: 1.5px solid var(--whatsapp);
  color: #25D366;
  font-weight: 700;
  padding: 14px 22px;
  border-radius: var(--radius-md);
  font-size: 0.95rem;
  transition: var(--transition);
}

.btn-whatsapp-hero:hover {
  background: var(--whatsapp);
  color: #fff;
  transform: translateY(-2px);
  box-shadow: 0 4px 15px rgba(37, 211, 102, 0.4);
}

.btn-whatsapp-hero i {
  font-size: 1.2rem;
}

.hero-trust-metrics {
  display: flex;
  align-items: center;
  gap: 22px;
  padding-top: 25px;
  border-top: 1px solid rgba(255, 255, 255, 0.12);
  flex-wrap: wrap;
}

.metric-item {
  display: flex;
  flex-direction: column;
}

.metric-num {
  font-family: var(--font-heading);
  font-size: 1.7rem;
  font-weight: 800;
  color: var(--accent-gold);
  line-height: 1.1;
}

.metric-label {
  font-size: 0.78rem;
  color: #94A3B8;
  font-weight: 500;
}

.metric-divider {
  width: 1px;
  height: 35px;
  background: rgba(255, 255, 255, 0.15);
}

/* Quick Enquiry Card in Hero */
.hero-card-wrapper {
  position: relative;
}

.quick-enquiry-card {
  background: rgba(255, 255, 255, 0.98);
  color: var(--text-main);
  padding: 32px 28px;
  border-radius: var(--radius-lg);
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.3);
}

.quick-enquiry-card .card-header {
  margin-bottom: 20px;
}

.chip-live {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--brand-emerald);
  font-size: 0.76rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 6px;
}

.chip-live i {
  font-size: 0.6rem;
  animation: pulseGreen 1.5s infinite;
}

@keyframes pulseGreen {
  0% { opacity: 0.4; }
  50% { opacity: 1; }
  100% { opacity: 0.4; }
}

.quick-enquiry-card h3 {
  font-size: 1.45rem;
  color: var(--primary);
  margin-bottom: 4px;
}

.quick-enquiry-card p {
  font-size: 0.88rem;
  color: var(--text-muted);
}

.quick-form {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.form-group label {
  font-size: 0.84rem;
  font-weight: 600;
  color: var(--text-main);
}

.form-row-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.input-with-icon {
  position: relative;
  display: flex;
  align-items: center;
}

.input-with-icon i {
  position: absolute;
  left: 14px;
  color: var(--text-light);
  font-size: 0.95rem;
  pointer-events: none;
}

.input-with-icon input,
.quick-form select,
.main-enquiry-form input,
.main-enquiry-form select,
.main-enquiry-form textarea {
  width: 100%;
  padding: 11px 14px 11px 40px;
  border: 1.5px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: #FFFFFF;
  color: var(--text-main);
  font-size: 0.92rem;
  transition: var(--transition);
}

.quick-form select,
.main-enquiry-form select {
  padding-left: 14px;
}

.input-with-icon input:focus,
.quick-form select:focus,
.main-enquiry-form input:focus,
.main-enquiry-form select:focus,
.main-enquiry-form textarea:focus {
  border-color: var(--brand-blue);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.12);
}

.btn-submit-hero {
  padding: 13px;
  margin-top: 6px;
  font-size: 1rem;
}

.form-privacy-note {
  font-size: 0.74rem;
  color: var(--text-light);
  text-align: center;
  margin-top: 6px;
}

/* --- Batch Ticker Strip --- */
.batch-ticker-section {
  background: var(--accent-gold);
  color: var(--primary-dark);
  padding: 10px 0;
  font-size: 0.88rem;
  font-weight: 600;
  overflow: hidden;
  box-shadow: inset 0 -2px 5px rgba(0, 0, 0, 0.1);
}

.ticker-container {
  display: flex;
  align-items: center;
  gap: 18px;
}

.ticker-label {
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-heading);
  letter-spacing: 0.04em;
  font-size: 0.85rem;
}

.ticker-scroll-wrapper {
  overflow: hidden;
  white-space: nowrap;
  position: relative;
  width: 100%;
}

.ticker-items {
  display: inline-block;
  animation: tickerMarquee 35s linear infinite;
  white-space: nowrap;
}

.ticker-items:hover {
  animation-play-state: paused;
}

.ticker-tag {
  display: inline-block;
  padding: 0 8px;
}

.ticker-separator {
  display: inline-block;
  padding: 0 6px;
  opacity: 0.5;
}

@keyframes tickerMarquee {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* --- Courses Section --- */
.courses-section {
  background-color: var(--bg-body);
}

.course-filters {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 45px;
}

.filter-btn {
  background: #FFFFFF;
  color: var(--text-muted);
  border: 1.5px solid var(--border-light);
  padding: 10px 22px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.92rem;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: var(--transition);
}

.filter-btn:hover {
  border-color: var(--primary);
  color: var(--primary);
}

.filter-btn.active {
  background: var(--primary);
  color: #FFFFFF;
  border-color: var(--primary);
  box-shadow: 0 4px 12px rgba(10, 30, 63, 0.2);
}

.courses-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(360px, 1fr));
  gap: 30px;
  margin-bottom: 50px;
}

.course-card {
  background: #FFFFFF;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-light);
  box-shadow: var(--shadow-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  position: relative;
  transition: var(--transition);
}

.course-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-xl);
  border-color: rgba(37, 99, 235, 0.3);
}

.course-badge {
  position: absolute;
  top: 14px;
  right: 14px;
  font-size: 0.72rem;
  font-weight: 800;
  padding: 4px 10px;
  border-radius: var(--radius-full);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  z-index: 3;
}

.course-badge.popular {
  background: var(--accent-gold);
  color: var(--primary-dark);
}

.course-badge.high-yield {
  background: var(--brand-emerald);
  color: #fff;
}

.course-badge.premier {
  background: var(--brand-purple);
  color: #fff;
}

.course-badge.foundation-badge {
  background: var(--brand-cyan);
  color: var(--primary-dark);
}

.course-badge.state-badge {
  background: #F97316;
  color: #fff;
}

.course-header-banner {
  padding: 24px 24px 18px 24px;
  color: #fff;
  position: relative;
}

.medical-gradient {
  background: linear-gradient(135deg, #065F46, #0D9488);
}

.engineering-gradient {
  background: linear-gradient(135deg, #1E3A8A, #2563EB);
}

.foundation-gradient {
  background: linear-gradient(135deg, #4C1D95, #7C3AED);
}

.civil-gradient {
  background: linear-gradient(135deg, #9A3412, #EA580C);
}

.course-stream {
  font-size: 0.78rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  opacity: 0.9;
  margin-bottom: 6px;
}

.course-title {
  color: #FFFFFF;
  font-size: 1.3rem;
  line-height: 1.3;
}

.course-body {
  padding: 22px 24px;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.course-desc {
  font-size: 0.9rem;
  color: var(--text-muted);
  line-height: 1.55;
  margin-bottom: 18px;
}

.course-meta-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 18px;
  font-size: 0.86rem;
  color: var(--text-main);
  background: var(--bg-subtle);
  padding: 12px 14px;
  border-radius: var(--radius-sm);
}

.course-meta-list li {
  display: flex;
  align-items: center;
  gap: 8px;
}

.course-meta-list li i {
  color: var(--brand-blue);
  width: 16px;
  font-size: 0.9rem;
}

.course-highlights {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 22px;
}

.highlight-chip {
  background: rgba(37, 99, 235, 0.08);
  color: var(--primary);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 3px 9px;
  border-radius: var(--radius-sm);
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.highlight-chip i {
  color: var(--brand-emerald);
}

.course-footer {
  margin-top: auto;
  display: flex;
  align-items: center;
  gap: 10px;
  padding-top: 14px;
  border-top: 1px solid var(--border-light);
}

.course-footer .btn {
  flex: 1;
}

/* Custom Course Box */
.custom-course-box {
  background: linear-gradient(135deg, #0A1E3F, #1E3A8A);
  color: #fff;
  border-radius: var(--radius-lg);
  padding: 32px 36px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
  flex-wrap: wrap;
  box-shadow: var(--shadow-lg);
}

.custom-box-text h4 {
  color: #FFFFFF;
  font-size: 1.3rem;
  margin-bottom: 6px;
}

.custom-box-text p {
  color: #CBD5E1;
  font-size: 0.95rem;
}

/* --- Why Choose Us Section --- */
.why-us-section {
  background-color: #FFFFFF;
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(350px, 1fr));
  gap: 28px;
  margin-bottom: 60px;
}

.feature-card {
  background: var(--bg-body);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  padding: 32px 26px;
  transition: var(--transition);
}

.feature-card:hover {
  transform: translateY(-5px);
  border-color: rgba(37, 99, 235, 0.25);
  box-shadow: var(--shadow-lg);
  background: #FFFFFF;
}

.feature-icon {
  width: 58px;
  height: 58px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  color: #fff;
  margin-bottom: 20px;
}

.bg-blue { background: linear-gradient(135deg, #1E40AF, #3B82F6); }
.bg-amber { background: linear-gradient(135deg, #D97706, #F59E0B); }
.bg-emerald { background: linear-gradient(135deg, #047857, #10B981); }
.bg-purple { background: linear-gradient(135deg, #6D28D9, #8B5CF6); }
.bg-rose { background: linear-gradient(135deg, #BE123C, #F43F5E); }
.bg-cyan { background: linear-gradient(135deg, #0E7490, #06B6D4); }

.feature-title {
  font-size: 1.22rem;
  margin-bottom: 10px;
}

.feature-desc {
  font-size: 0.92rem;
  color: var(--text-muted);
  line-height: 1.6;
}

/* Pedagogy Flow */
.pedagogy-container {
  background: var(--bg-subtle);
  border-radius: var(--radius-lg);
  padding: 40px 30px;
  border: 1px solid var(--border-light);
}

.pedagogy-heading {
  font-size: 1.45rem;
  margin-bottom: 35px;
}

.pedagogy-steps {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  flex-wrap: wrap;
}

.step-card {
  flex: 1;
  min-width: 200px;
  background: #FFFFFF;
  padding: 24px 20px;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  position: relative;
  border-top: 3.5px solid var(--brand-blue);
}

.step-num {
  font-family: var(--font-heading);
  font-size: 1.8rem;
  font-weight: 800;
  color: rgba(37, 99, 235, 0.18);
  position: absolute;
  top: 10px;
  right: 14px;
}

.step-card h4 {
  font-size: 1.05rem;
  margin-bottom: 8px;
}

.step-card p {
  font-size: 0.85rem;
  color: var(--text-muted);
  line-height: 1.5;
}

.step-arrow {
  color: var(--text-light);
  font-size: 1.2rem;
}

/* --- Scholarship V-SAT Section --- */
.scholarship-section {
  background: linear-gradient(145deg, #06152B, #0A1E3F);
  color: #fff;
}

.scholarship-card {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 50px;
  align-items: center;
}

.scholarship-title {
  color: #fff;
  font-size: 2.2rem;
  margin-bottom: 16px;
}

.scholarship-desc {
  color: #CBD5E1;
  font-size: 1.05rem;
  margin-bottom: 24px;
  line-height: 1.6;
}

.scholarship-points {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.scholarship-points li {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.95rem;
  color: #E2E8F0;
}

.scholarship-points li i {
  color: var(--accent-gold);
}

/* Calculator Box */
.scholarship-calc-box {
  background: #FFFFFF;
  color: var(--text-main);
  border-radius: var(--radius-lg);
  padding: 32px 28px;
  box-shadow: var(--shadow-xl);
}

.scholarship-calc-box h3 {
  font-size: 1.35rem;
  margin-bottom: 18px;
  color: var(--primary);
  border-bottom: 2px solid var(--accent-gold-light);
  padding-bottom: 10px;
}

.calc-form {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.calc-input {
  width: 100%;
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  border: 1.5px solid var(--border-light);
  font-weight: 500;
}

.range-display {
  display: flex;
  align-items: center;
  gap: 15px;
}

.calc-slider {
  flex-grow: 1;
  accent-color: var(--accent-gold);
  cursor: pointer;
  height: 6px;
}

.range-val {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 1.15rem;
  color: var(--primary);
  min-width: 50px;
  text-align: right;
}

.calc-result {
  background: var(--bg-subtle);
  border: 1.5px dashed var(--accent-gold);
  border-radius: var(--radius-md);
  padding: 16px;
  text-align: center;
  margin-top: 5px;
}

.calc-result-label {
  display: block;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
}

.calc-result-amount {
  display: block;
  font-family: var(--font-heading);
  font-size: 1.85rem;
  font-weight: 800;
  color: var(--accent-gold-hover);
  margin: 4px 0;
}

.calc-result-note {
  font-size: 0.8rem;
  color: var(--brand-emerald);
  font-weight: 600;
}

/* --- Results & Toppers Section --- */
.results-section {
  background: var(--bg-body);
}

.toppers-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(270px, 1fr));
  gap: 25px;
  margin-bottom: 45px;
}

.topper-card {
  background: #FFFFFF;
  border-radius: var(--radius-lg);
  padding: 28px 22px;
  border: 1px solid var(--border-light);
  box-shadow: var(--shadow-md);
  display: flex;
  flex-direction: column;
  position: relative;
  transition: var(--transition);
}

.topper-card:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-xl);
  border-color: rgba(37, 99, 235, 0.3);
}

.topper-rank-badge {
  position: absolute;
  top: 16px;
  right: 16px;
  background: #DCFCE7;
  color: #15803D;
  font-weight: 800;
  font-size: 0.76rem;
  padding: 4px 10px;
  border-radius: var(--radius-full);
}

.topper-rank-badge.rank-jee {
  background: #DBEAFE;
  color: #1E40AF;
}

.topper-rank-badge.rank-neet {
  background: #FEF3C7;
  color: #B45309;
}

.topper-rank-badge.rank-tnpsc {
  background: #FEE2E2;
  color: #B91C1C;
}

.topper-avatar {
  margin-bottom: 16px;
}

.avatar-circle {
  width: 62px;
  height: 62px;
  border-radius: 50%;
  background: linear-gradient(135deg, #059669, #10B981);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 1.3rem;
  font-weight: 700;
  box-shadow: 0 4px 12px rgba(16, 185, 129, 0.3);
}

.avatar-jee { background: linear-gradient(135deg, #1E40AF, #3B82F6); box-shadow: 0 4px 12px rgba(59, 130, 246, 0.3); }
.avatar-doctor { background: linear-gradient(135deg, #D97706, #F59E0B); box-shadow: 0 4px 12px rgba(245, 158, 11, 0.3); }
.avatar-civil { background: linear-gradient(135deg, #BE123C, #E11D48); box-shadow: 0 4px 12px rgba(225, 29, 72, 0.3); }

.topper-name {
  font-size: 1.18rem;
  margin-bottom: 2px;
}

.topper-school {
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-bottom: 14px;
}

.topper-achievement {
  background: var(--bg-subtle);
  padding: 10px 12px;
  border-radius: var(--radius-sm);
  margin-bottom: 14px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.achieve-score {
  font-weight: 700;
  color: var(--primary);
  font-size: 0.9rem;
}

.achieve-score i {
  color: var(--accent-gold);
}

.achieve-admit {
  font-size: 0.78rem;
  color: var(--brand-emerald);
  font-weight: 600;
}

.topper-quote {
  font-size: 0.85rem;
  color: var(--text-muted);
  font-style: italic;
  line-height: 1.5;
  margin-top: auto;
}

.reviews-strip {
  background: #FFFFFF;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  padding: 22px 30px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 20px;
  box-shadow: var(--shadow-sm);
}

.google-badge {
  display: flex;
  align-items: center;
  gap: 16px;
}

.google-badge i {
  font-size: 2.2rem;
  color: #EA4335;
}

.google-badge div {
  display: flex;
  flex-direction: column;
}

.google-badge strong {
  font-size: 1.1rem;
  color: var(--primary);
}

.google-badge span {
  font-size: 0.82rem;
  color: var(--text-muted);
}

.verified-tags {
  display: flex;
  align-items: center;
  gap: 20px;
  flex-wrap: wrap;
  font-size: 0.86rem;
  font-weight: 600;
  color: var(--text-main);
}

.verified-tags i {
  color: var(--brand-emerald);
}

/* --- About Section --- */
.about-section {
  background: #FFFFFF;
}

.about-grid {
  display: grid;
  grid-template-columns: 0.95fr 1.05fr;
  gap: 50px;
  align-items: center;
}

.about-visual-card {
  background: linear-gradient(135deg, #0A1E3F, #1E3A8A);
  border-radius: var(--radius-lg);
  padding: 40px 32px;
  color: #fff;
  position: relative;
  box-shadow: var(--shadow-xl);
}

.visual-badge {
  display: flex;
  align-items: baseline;
  gap: 12px;
  margin-bottom: 30px;
  padding-bottom: 25px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);
}

.visual-badge .years {
  font-family: var(--font-heading);
  font-size: 3.5rem;
  font-weight: 800;
  color: var(--accent-gold);
  line-height: 1;
}

.visual-badge .label {
  font-size: 1.05rem;
  color: #E2E8F0;
  max-width: 180px;
  line-height: 1.3;
}

.about-highlights-list {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.about-highlight-box {
  display: flex;
  align-items: center;
  gap: 16px;
  background: rgba(255, 255, 255, 0.08);
  padding: 16px 18px;
  border-radius: var(--radius-md);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.about-highlight-box i {
  font-size: 1.5rem;
  color: var(--accent-gold);
}

.about-highlight-box strong {
  display: block;
  font-size: 1.05rem;
  color: #fff;
}

.about-highlight-box p {
  font-size: 0.82rem;
  color: #CBD5E1;
}

.about-lead {
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--primary);
  line-height: 1.6;
  margin-bottom: 16px;
}

.about-body {
  font-size: 0.95rem;
  color: var(--text-muted);
  line-height: 1.7;
  margin-bottom: 24px;
}

.director-message {
  background: var(--bg-body);
  border-left: 4px solid var(--accent-gold);
  padding: 20px 24px;
  border-radius: var(--radius-md);
  margin-bottom: 28px;
  display: flex;
  gap: 16px;
  align-items: flex-start;
}

.director-avatar {
  width: 48px;
  height: 48px;
  background: var(--primary);
  color: var(--accent-gold);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.3rem;
  flex-shrink: 0;
}

.director-info blockquote {
  font-size: 0.92rem;
  font-style: italic;
  color: var(--text-main);
  margin-bottom: 8px;
  line-height: 1.55;
}

.director-info strong {
  display: block;
  font-size: 0.9rem;
  color: var(--primary);
}

.director-info span {
  font-size: 0.78rem;
  color: var(--text-muted);
}

.about-cta-row {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
}

/* --- Chennai Campuses Section --- */
.campuses-section {
  background-color: var(--bg-body);
}

.campus-tabs {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 35px;
}

.campus-tab-btn {
  background: #FFFFFF;
  border: 1.5px solid var(--border-light);
  padding: 12px 24px;
  border-radius: var(--radius-md);
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-muted);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: var(--transition);
}

.campus-tab-btn:hover {
  border-color: var(--primary);
  color: var(--primary);
}

.campus-tab-btn.active {
  background: var(--primary);
  color: #FFFFFF;
  border-color: var(--primary);
  box-shadow: 0 4px 12px rgba(10, 30, 63, 0.2);
}

.campus-card {
  display: none;
  background: #FFFFFF;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-light);
  box-shadow: var(--shadow-lg);
  padding: 36px 32px;
  transition: var(--transition);
}

.campus-card.active {
  display: block;
  animation: fadeIn 0.4s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.campus-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 15px;
  margin-bottom: 20px;
  padding-bottom: 18px;
  border-bottom: 1px solid var(--border-light);
}

.campus-label {
  display: inline-block;
  font-size: 0.78rem;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--accent-gold-hover);
  letter-spacing: 0.06em;
}

.campus-header h3 {
  font-size: 1.6rem;
  color: var(--primary);
}

.metro-badge {
  background: #EFF6FF;
  color: #1D4ED8;
  font-weight: 700;
  font-size: 0.82rem;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 1px solid #BFDBFE;
}

.campus-address {
  font-size: 1rem;
  color: var(--text-main);
  margin-bottom: 25px;
  line-height: 1.6;
}

.campus-meta-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 20px;
  margin-bottom: 30px;
  background: var(--bg-subtle);
  padding: 22px;
  border-radius: var(--radius-md);
}

.cm-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.cm-item i {
  color: var(--brand-blue);
  font-size: 1.1rem;
  margin-top: 2px;
}

.cm-item strong {
  display: block;
  font-size: 0.8rem;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 2px;
}

.cm-item span, .cm-item a {
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--text-main);
}

.cm-item a:hover {
  color: var(--brand-blue);
}

.campus-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

/* --- Student Enquiry Form Section --- */
.enquiry-section {
  background: linear-gradient(135deg, #0A1E3F 0%, #102A54 100%);
  color: #fff;
}

.enquiry-card-wrapper {
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  gap: 50px;
  align-items: flex-start;
}

.enquiry-title {
  color: #FFFFFF;
  font-size: 2.3rem;
  margin-bottom: 16px;
}

.enquiry-text {
  color: #CBD5E1;
  font-size: 1.05rem;
  line-height: 1.6;
  margin-bottom: 32px;
}

.counselor-perks {
  display: flex;
  flex-direction: column;
  gap: 20px;
  margin-bottom: 35px;
}

.perk-item {
  display: flex;
  align-items: flex-start;
  gap: 15px;
}

.perk-item i {
  font-size: 1.4rem;
  color: var(--accent-gold);
  background: rgba(245, 158, 11, 0.15);
  padding: 12px;
  border-radius: var(--radius-md);
}

.perk-item strong {
  display: block;
  font-size: 1rem;
  color: #FFFFFF;
  margin-bottom: 2px;
